const walletSamples=[{id:'DEMO-MC-AINP',type:'Microcredential',title:'Microcredential in AI-Native Productivity',code:'MC-AINP'},{id:'DEMO-CT-AGNC',type:'Certificate',title:'Certificate in No-Code Generative and Agentic AI',code:'CT-AGNC'}];
function walletBadge(c){return `<div class="wallet-seal" aria-label="Sample ${esc(c.type)} badge"><small>SCHOLARION ACADEMY</small><span>${c.type}</span><strong>${esc(c.title)}</strong><small>${c.code}</small><b>SAMPLE</b></div>`;}
function referenceWallet(){const links=[['Dashboard','dashboard'],['Courses','courses'],['Calendar','calendar'],['Agents','agents'],['Certificates','credential-pipeline'],['My credentials','credentials'],['Course work','assignments'],['Library','resources'],['Help','help']];return `<div class="oak-wallet"><header class="oak-header"><a href="#home"><strong>Scholarion Academy</strong><span>Knowledge. Purpose. Global Impact.</span></a><div><b class="oak-demo">Demonstration data</b><span>Sample learner · Student</span><a class="oak-switch" href="#signin">Switch workspace</a></div></header><div class="oak-layout"><aside class="oak-nav"><small>Learning</small><nav aria-label="Wallet navigation">${links.map(([n,r])=>`<a href="#${r}" ${r==='credentials'?'aria-current="page"':''}>${n}</a>`).join('')}</nav><small>My records</small><a href="#grades">Gradebook</a><a href="#pathways">Learning pathways</a></aside><main class="oak-main"><div class="oak-title"><div><h1>My credentials</h1><p>Your certificates and digital badges, together in one wallet.</p></div><button data-wallet="export">Export sample records</button></div><p class="oak-note">Design preview · These two illustrative records are not issued, signed, or verified credentials. Downloads and public sharing become available after issuance.</p>${walletSamples.map(c=>`<article class="oak-card">${walletBadge(c)}<div class="oak-details"><small><b>${c.type} · Open Badges 3.0 planned</b></small><h2>${esc(c.title)}</h2><p>${c.code} · Not issued</p><div class="oak-status">Sample — issuance pending</div><p>Preview ID <code>${c.id}</code></p><div class="oak-actions"><button class="oak-primary" data-wallet="certificate" data-id="${c.id}">Certificate preview</button><button disabled title="Available after signed badge issuance">Badge image (PNG)</button><button disabled title="Available after signed badge issuance">Open Badge (JSON)</button></div><div class="oak-actions"><button disabled>Copy share link</button><button data-wallet="qr">Show QR code</button><button disabled>Add to LinkedIn</button><button data-wallet="verification">Verification page</button><button data-wallet="record" data-id="${c.id}">Issuance record</button></div></div></article>`).join('')}<section class="oak-card oak-notices"><h2>In-app notices</h2>${credentialModel.notices.map(n=>`<p>${esc(n)}</p>`).join('')||'<p>No issuance notices yet.</p>'}<a href="#credential-pipeline">View completion requirements and issuance readiness →</a></section></main></div></div>`;}
const beforeReferenceWallet=render;
render=function(){if(location.hash.slice(1)==='credentials'){document.getElementById('app').innerHTML=referenceWallet();document.title='My credentials · Scholarion Academy';}else beforeReferenceWallet();};
document.addEventListener('click',e=>{const t=e.target.closest('[data-wallet]');if(!t)return;const c=walletSamples.find(x=>x.id===t.dataset.id);switch(t.dataset.wallet){case'export':download('scholarion-wallet-design-samples.json',JSON.stringify({type:'DesignPreview',issued:false,signed:false,records:walletSamples},null,2),'application/json');break;case'certificate':modal('Certificate design preview',certificateDesign(c));break;case'qr':modal('Credential QR code','<p>A QR code will link to the public verification record after issuance. No verification URL exists for these sample records.</p>');break;case'verification':modal('Verification pending','<p>This is an unissued design sample. Public verification requires a signed credential and a connected verification service.</p>');break;case'record':modal('Issuance record',`<p>Preview ID: <code>${esc(c.id)}</code></p><p>Status: not issued. There is no issuance ledger entry for this design sample.</p>${btn('View attempt ledger','#credential-pipeline',true)}`);break;}});
render();
function certificateDesign(c){const courses=c.code==='CT-AGNC'?[['AGA501','Foundations of Generative AI and Large Language Models'],['AGA550','No-Code and Low-Code Agent Building'],['AGA590','AI-Native Productivity: Workflows and Agents']]:[];return `<div class="oak-certificate sample-certificate"><header><h2>Scholarion Academy</h2><p>Knowledge. Purpose. Global Impact.</p></header><div class="cert-body"><p>This certifies that</p><h3>Zainab Bello (demo)</h3><p>has completed every requirement of the</p><h4>${esc(c.title)}</h4><p class="cert-meta">${c.type}${courses.length?' · 3 courses':''}</p><ul>${courses.map(([code,title])=>`<li>${code} &nbsp; ${esc(title)}</li>`).join('')}</ul></div><footer><div class="cert-signatures"><span>Office of the Registrar</span><div class="cert-qr-placeholder">QR code<br>pending issuance</div><span>Not issued · Design sample</span></div><p>Preview ID: ${esc(c.id)} · Verification unavailable · Unsigned demonstration</p><p class="cert-disclaimer">SAMPLE DATA — NOT AN AWARD OR PROOF OF COMPLETION.</p></footer></div><p class="cert-context">Course names and sample recipient reproduced from your reference. They do not establish approved eligibility requirements.</p>`;}

// Formal diploma-inspired composition using the academy's own certificate wording.
certificateDesign=function(c){return `<div class="formal-certificate"><header><h2>Scholarion Academy</h2><img class="formal-header-logo" src="assets/scholarion-academy-seal.png" alt="Scholarion Academy logo"></header><div class="formal-copy"><p>In recognition of dedication to learning<br>and the successful completion of the prescribed program,<br>this certificate is presented to</p><h3>Zainab Bello (demo)</h3><p>for completion of the</p><h4>${esc(c.title)}</h4><p class="formal-description">Recognizing the knowledge and practical skills developed through<br>structured study, applied learning, and project work.</p></div><footer><div class="formal-signature"><span>Signature pending</span><strong>Office of the Registrar</strong></div><div class="formal-seal"><span>SCHOLARION</span><strong>S</strong><span>LEARNING · ACHIEVEMENT</span><b>SAMPLE</b></div><div class="formal-signature"><span>Signature pending</span><strong>Program Director</strong></div></footer><p class="formal-disclaimer">DEMONSTRATION ONLY · NOT ISSUED · NOT A DEGREE OR VERIFIED AWARD<br>Preview ID: ${esc(c.id)} · Verification and QR code pending issuance</p></div><p class="cert-context">Certificate design preview. Recipient and completion statement are illustrative; no credential has been issued.</p>`;};



// Approved badge artwork: preserve all variants and use course-specific designs in the wallet.
const approvedBadgeArt=[['Professional development · Shield','scholarion-professional-development-badge.png'],['Professional development · Seal','scholarion-professional-development-badge-v2.png'],['AI-Native Productivity','scholarion-ai-native-productivity-badge.png'],['No-Code Generative & Agentic AI','scholarion-no-code-agentic-ai-badge.png']];
walletBadge=function(c){const file=c.code==='MC-AINP'?'scholarion-ai-native-productivity-badge.png':'scholarion-no-code-agentic-ai-badge.png';return `<img class="wallet-approved-badge" src="assets/${file}" alt="${esc(c.title)} badge artwork">`;};
const walletBeforeApprovedArt=referenceWallet;
referenceWallet=function(){return walletBeforeApprovedArt().replace('</main>',`<section class="oak-card oak-notices"><h2>Academy badge collection</h2><p>Approved artwork for course completion and professional development. Artwork downloads do not contain signed credentials.</p><div class="approved-badge-gallery">${approvedBadgeArt.map(([name,file])=>`<figure><img src="assets/${file}" alt="${esc(name)} badge"><figcaption>${esc(name)}</figcaption><a href="assets/${file}" download>Download artwork (PNG)</a></figure>`).join('')}</div></section></main>`);};
render();
